   107|
   108|export interface InvestorStatement {
   109|  statementId: string;
   110|  accountId: string;
   111|  userId: string;
   112|  period: StatementPeriod;
   113|  periodStart: string;
   114|  periodEnd: string;
   115|  openingBalance: number;
   116|  deposits: number;
   117|  withdrawals: number;
   118|  investments: number;
   119|  distributions: number;
   120|  fees: number;
