   122|  roiPercent: number | null;
   123|  irrPercent: number | null;
   124|  taxSummary: {
   125|    taxableDistributions: number;
   126|    taxableInterest: number;
   127|    taxableDividends: number;
   128|    realizedGains: number;
   129|    totalTaxable: number;
