   134|
   135|function periodStartDate(period: StatementPeriod, end: Date): Date {
   136|  const start = new Date(end);
   137|  switch (period) {
   138|    case 'daily': start.setUTCDate(start.getUTCDate() - 1); break;
   139|    case 'weekly': start.setUTCDate(start.getUTCDate() - 7); break;
   140|    case 'monthly': start.setUTCMonth(start.getUTCMonth() - 1); break;
   141|    case 'quarterly': start.setUTCMonth(start.getUTCMonth() - 3); break;
   142|    case 'yearly': start.setUTCFullYear(start.getUTCFullYear() - 1); break;
   143|  }
   144|  return start;
   145|}
   146|
   147|function signedCashEffect(entry: LedgerEntry): number {
   148|  if (entry.status !== 'completed') return 0;
   149|  switch (entry.type) {
   150|    case 'deposit':
   151|    case 'distribution':
   152|    case 'dividend':
   153|    case 'interest':
   154|    case 'profit':
   155|    case 'commission':
   156|    case 'refund':
   157|      return entry.amount;
   158|    case 'withdrawal':
   159|    case 'investment':
   160|    case 'loss':
   161|    case 'fee':
   162|      return -entry.amount;
   163|    case 'transfer':
   164|    case 'adjustment':
   165|      return entry.amount;
   166|    default:
   167|      return 0;
   168|  }
   169|}
   170|
   171|/** Generates a statement for one account across the requested period. */
   172|export async function generateStatement(accountId: string, period: StatementPeriod): Promise<InvestorStatement> {
   173|  const account = await getInvestorAccount(accountId);
   174|  if (!account) throw new Error(`Account not found: ${accountId}`);
   175|  const allEntries = (await listLedger({ accountId, limit: 1000 })).slice().reverse(); // chronological
   176|  const end = new Date();
   177|  const start = periodStartDate(period, end);
   178|
   179|  let openingBalance = 0;
   180|  const inPeriod: LedgerEntry[] = [];
   181|  for (const entry of allEntries) {
   182|    const at = new Date(entry.timestamp);
   183|    if (at < start) openingBalance += signedCashEffect(entry);
   184|    else if (at <= end) inPeriod.push(entry);
   185|  }
   186|
   187|  const sumType = (types: string[]): number =>
   188|    round2(inPeriod.filter((e) => types.includes(e.type) && e.status === 'completed').reduce((s, e) => s + e.amount, 0));
   189|
   190|  const deposits = sumType(['deposit']);
   191|  const withdrawals = sumType(['withdrawal']);
   192|  const investments = sumType(['investment']);
   193|  const distributions = sumType(['distribution']);
   194|  const fees = sumType(['fee']);
   195|  const endingBalance = round2(openingBalance + inPeriod.reduce((s, e) => s + signedCashEffect(e), 0));
   196|
   197|  const summary = await getAccountSummary(accountId);
   198|  const taxableDistributions = distributions;
   199|  const taxableInterest = sumType(['interest']);
   200|  const taxableDividends = sumType(['dividend']);
   201|  const realizedGains = sumType(['profit']);
   202|
   203|  const cashflows = inPeriod
   204|    .filter((e) => e.status === 'completed' && (e.type === 'investment' || e.type === 'distribution' || e.type === 'dividend'))
   205|    .map((e) => ({ amount: e.type === 'investment' ? -e.amount : e.amount, date: new Date(e.timestamp) }));
   206|
   207|  const statement: InvestorStatement = {
   208|    statementId: makeId('stmt'),
   209|    accountId,
   210|    userId: account.userId,
   211|    period,
   212|    periodStart: start.toISOString(),
   213|    periodEnd: end.toISOString(),
   214|    openingBalance: round2(openingBalance),
   215|    deposits,
   216|    withdrawals,
   217|    investments,
   218|    distributions,
   219|    fees,
   220|    endingBalance,
   221|    roiPercent: summary?.roiPercent ?? null,
   222|    irrPercent: summary?.irrPercent ?? computeIRRPercent(cashflows),
   223|    taxSummary: {
   224|      taxableDistributions,
   225|      taxableInterest,
   226|      taxableDividends,
   227|      realizedGains,
   228|      totalTaxable: round2(taxableDistributions + taxableInterest + taxableDividends + realizedGains),
   229|    },
   230|    lineItems: inPeriod.map((e) => ({
   231|      transactionId: e.transactionId,
   232|      date: e.date,
   233|      type: e.type,
   234|      amount: e.amount,
   235|      status: e.status,
   236|      memo: e.memo,
   237|    })),
   238|    generatedAt: nowIso(),
   239|  };
   240|  await appendFinanceEvent({ action: 'statement_generated', statementId: statement.statementId, accountId, period });
   241|  return statement;
   242|}
