   244|/** CSV export (also served as the Excel-compatible format). */
   245|export function statementToCSV(statement: InvestorStatement): string {
   246|  const lines: string[] = [];
   247|  lines.push('IVX INVESTOR STATEMENT');
   248|  lines.push(`Statement ID,${statement.statementId}`);
   249|  lines.push(`Account,${statement.accountId}`);
   250|  lines.push(`Period,${statement.period},${statement.periodStart},${statement.periodEnd}`);
   251|  lines.push('');
   252|  lines.push('Summary,Amount');
   253|  lines.push(`Opening Balance,${statement.openingBalance}`);
   254|  lines.push(`Deposits,${statement.deposits}`);
   255|  lines.push(`Withdrawals,${statement.withdrawals}`);
   256|  lines.push(`Investments,${statement.investments}`);
   257|  lines.push(`Distributions,${statement.distributions}`);
   258|  lines.push(`Fees,${statement.fees}`);
   259|  lines.push(`Ending Balance,${statement.endingBalance}`);
